import{_ as t,a as d,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Get Shipment","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-shipment-detail-gql","title":"Get Shipment","description":"Fetch a single shipment by id, with the order/customer context, both addresses, and the shipped line items inlined.","query":"query AdminShipment($id: ID!) {\\n  adminShipment(id: $id) {\\n    id\\n    _id\\n    orderId\\n    orderIncrementId\\n    shippedTo\\n    orderDate\\n    orderStatus\\n    orderStatusLabel\\n    channelName\\n    customerName\\n    customerEmail\\n    paymentMethod\\n    paymentTitle\\n    orderCurrencyCode\\n    shippingMethod\\n    shippingTitle\\n    baseShippingAmount\\n    formattedBaseShippingAmount\\n    status\\n    totalQty\\n    totalWeight\\n    carrierCode\\n    carrierTitle\\n    trackNumber\\n    emailSent\\n    inventorySourceId\\n    inventorySourceName\\n    billingAddress\\n    shippingAddress\\n    createdAt\\n    updatedAt\\n    items\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/admin/shipments/7\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminShipment\\": {\\n      \\"id\\": \\"/api/admin/shipments/7\\",\\n      \\"_id\\": 7,\\n      \\"orderId\\": 8,\\n      \\"orderIncrementId\\": \\"00000000008\\",\\n      \\"shippedTo\\": \\"John Doe\\",\\n      \\"orderDate\\": \\"2026-05-20 10:00:00\\",\\n      \\"orderStatus\\": \\"processing\\",\\n      \\"orderStatusLabel\\": \\"Processing\\",\\n      \\"channelName\\": \\"Default\\",\\n      \\"customerName\\": \\"John Doe\\",\\n      \\"customerEmail\\": \\"john.doe@example.com\\",\\n      \\"paymentMethod\\": \\"cashondelivery\\",\\n      \\"paymentTitle\\": \\"Cash On Delivery\\",\\n      \\"orderCurrencyCode\\": \\"USD\\",\\n      \\"shippingMethod\\": \\"free_free\\",\\n      \\"shippingTitle\\": \\"Free Shipping - Free Shipping\\",\\n      \\"baseShippingAmount\\": 0,\\n      \\"formattedBaseShippingAmount\\": \\"$0.00\\",\\n      \\"status\\": null,\\n      \\"totalQty\\": 2,\\n      \\"totalWeight\\": null,\\n      \\"carrierCode\\": null,\\n      \\"carrierTitle\\": \\"UPS\\",\\n      \\"trackNumber\\": \\"1Z999AA1\\",\\n      \\"emailSent\\": false,\\n      \\"inventorySourceId\\": 1,\\n      \\"inventorySourceName\\": \\"Default\\",\\n      \\"billingAddress\\": {\\n        \\"id\\": 16,\\n        \\"addressType\\": \\"order_billing\\",\\n        \\"firstName\\": \\"John\\",\\n        \\"lastName\\": \\"Doe\\",\\n        \\"city\\": \\"Los Angeles\\",\\n        \\"country\\": \\"US\\",\\n        \\"postcode\\": \\"90001\\",\\n        \\"email\\": \\"john.doe@example.com\\",\\n        \\"phone\\": \\"5551234567\\"\\n      },\\n      \\"shippingAddress\\": {\\n        \\"id\\": 15,\\n        \\"addressType\\": \\"order_shipping\\",\\n        \\"firstName\\": \\"John\\",\\n        \\"lastName\\": \\"Doe\\",\\n        \\"city\\": \\"Los Angeles\\",\\n        \\"country\\": \\"US\\",\\n        \\"postcode\\": \\"90001\\",\\n        \\"email\\": \\"john.doe@example.com\\",\\n        \\"phone\\": \\"5551234567\\"\\n      },\\n      \\"createdAt\\": \\"2026-05-20 12:00:00\\",\\n      \\"updatedAt\\": \\"2026-05-20 12:00:00\\",\\n      \\"items\\": [\\n        {\\n          \\"id\\": 11,\\n          \\"orderItemId\\": 42,\\n          \\"sku\\": \\"TSHIRT-RED-M\\",\\n          \\"name\\": \\"Red T-Shirt\\",\\n          \\"qty\\": 2\\n        }\\n      ]\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/orders/get-shipment.md","filePath":"api/graphql-api/admin/sales/orders/get-shipment.md","lastUpdated":1787725411000}'),n={name:"api/graphql-api/admin/sales/orders/get-shipment.md"};function i(c,e,a,s,h,p){return o(),d("div",null,e[0]||(e[0]=[r('<h1 id="get-shipment" tabindex="-1">Get Shipment <a class="header-anchor" href="#get-shipment" aria-label="Permalink to &quot;Get Shipment&quot;">​</a></h1><p>GraphQL counterpart of <code>GET /api/admin/shipments/{id}</code>. Returns a single shipment with the order/customer context, both addresses, and the shipped line <code>items</code> inlined — everything the listing leaves out.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>adminShipment(id: ID!)</code></td><td>Query</td></tr></tbody></table><p>Pass the shipment IRI (<code>/api/admin/shipments/{id}</code>) as <code>id</code>. Permission: <code>sales.shipments.view</code>.</p><h3 id="nested-objects-are-returned-whole" tabindex="-1">Nested Objects Are Returned Whole <a class="header-anchor" href="#nested-objects-are-returned-whole" aria-label="Permalink to &quot;Nested Objects Are Returned Whole&quot;">​</a></h3><p><code>billingAddress</code>, <code>shippingAddress</code> and <code>items</code> are returned as JSON — <strong>query them bare, without a sub-selection</strong> (<code>shippingAddress</code>, not <code>shippingAddress { … }</code>). The whole object/array comes back. The keys inside each are listed below for reference.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID</code></td><td>Resource identifier (IRI form).</td></tr><tr><td><code>_id</code></td><td><code>Int</code></td><td>Numeric shipment id.</td></tr><tr><td><code>orderId</code></td><td><code>Int</code></td><td>Id of the parent order.</td></tr><tr><td><code>orderIncrementId</code></td><td><code>String</code></td><td>Human-facing number of the parent order.</td></tr><tr><td><code>shippedTo</code></td><td><code>String</code></td><td>The name on the order&#39;s shipping address.</td></tr><tr><td><code>orderDate</code></td><td><code>String</code></td><td>When the order was placed.</td></tr><tr><td><code>orderStatus</code></td><td><code>String</code></td><td>Parent order status code.</td></tr><tr><td><code>orderStatusLabel</code></td><td><code>String</code></td><td>Parent order status display label.</td></tr><tr><td><code>channelName</code></td><td><code>String</code></td><td>Sales channel the order belongs to.</td></tr><tr><td><code>customerName</code></td><td><code>String</code></td><td>Name of the customer who placed the order.</td></tr><tr><td><code>customerEmail</code></td><td><code>String</code></td><td>Email of the customer who placed the order.</td></tr><tr><td><code>paymentMethod</code></td><td><code>String</code></td><td>The order&#39;s payment method code (e.g. <code>cashondelivery</code>).</td></tr><tr><td><code>paymentTitle</code></td><td><code>String</code></td><td>The payment method&#39;s display title.</td></tr><tr><td><code>orderCurrencyCode</code></td><td><code>String</code></td><td>Currency the order was placed in (e.g. <code>USD</code>).</td></tr><tr><td><code>shippingMethod</code></td><td><code>String</code></td><td>The order&#39;s shipping method code — may be <code>null</code>.</td></tr><tr><td><code>shippingTitle</code></td><td><code>String</code></td><td>The shipping method&#39;s display title — may be <code>null</code>.</td></tr><tr><td><code>baseShippingAmount</code></td><td><code>Float</code></td><td>Shipping price in the store&#39;s base currency — may be <code>null</code>.</td></tr><tr><td><code>formattedBaseShippingAmount</code></td><td><code>String</code></td><td>The same shipping price pre-formatted for display — may be <code>null</code>.</td></tr><tr><td><code>status</code></td><td><code>String</code></td><td>Shipment status — often <code>null</code>.</td></tr><tr><td><code>totalQty</code></td><td><code>Float</code></td><td>Total quantity shipped across all line items.</td></tr><tr><td><code>totalWeight</code></td><td><code>Float</code></td><td>Combined weight of the shipment — may be <code>null</code>.</td></tr><tr><td><code>carrierCode</code></td><td><code>String</code></td><td>Shipping carrier code — may be <code>null</code>.</td></tr><tr><td><code>carrierTitle</code></td><td><code>String</code></td><td>Shipping carrier display name — may be <code>null</code>.</td></tr><tr><td><code>trackNumber</code></td><td><code>String</code></td><td>Carrier tracking number — may be <code>null</code>.</td></tr><tr><td><code>emailSent</code></td><td><code>Boolean</code></td><td>Whether the shipment notification email was sent.</td></tr><tr><td><code>inventorySourceId</code></td><td><code>Int</code></td><td>Id of the inventory source the items shipped from.</td></tr><tr><td><code>inventorySourceName</code></td><td><code>String</code></td><td>Name of the inventory source (warehouse) the items shipped from.</td></tr><tr><td><code>billingAddress</code></td><td><code>JSON</code></td><td>The order&#39;s billing address — see below.</td></tr><tr><td><code>shippingAddress</code></td><td><code>JSON</code></td><td>The order&#39;s shipping address — see below.</td></tr><tr><td><code>createdAt</code></td><td><code>String</code></td><td>When the shipment was created.</td></tr><tr><td><code>updatedAt</code></td><td><code>String</code></td><td>When the shipment was last updated.</td></tr><tr><td><code>items</code></td><td><code>JSON</code></td><td>The shipped line items — see below.</td></tr></tbody></table><h3 id="payment-and-shipping" tabindex="-1">Payment and Shipping <a class="header-anchor" href="#payment-and-shipping" aria-label="Permalink to &quot;Payment and Shipping&quot;">​</a></h3><p>Mirrors the &quot;Payment and Shipping&quot; panel on the admin Shipment view — the order&#39;s payment and shipping details carried alongside the shipment. These are flat scalar fields and resolve normally (select them directly, no sub-selection). <code>shippingMethod</code>, <code>shippingTitle</code>, <code>baseShippingAmount</code> and <code>formattedBaseShippingAmount</code> are <code>null</code> when the order had no shipping method (e.g. virtual/free).</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>paymentMethod</code></td><td><code>String</code></td><td>The order&#39;s payment method code (e.g. <code>cashondelivery</code>).</td></tr><tr><td><code>paymentTitle</code></td><td><code>String</code></td><td>The payment method&#39;s display title (e.g. <code>Cash On Delivery</code>).</td></tr><tr><td><code>orderCurrencyCode</code></td><td><code>String</code></td><td>Currency the order was placed in (e.g. <code>USD</code>).</td></tr><tr><td><code>shippingMethod</code></td><td><code>String</code></td><td>The order&#39;s shipping method code (e.g. <code>free_free</code>) — may be <code>null</code>.</td></tr><tr><td><code>shippingTitle</code></td><td><code>String</code></td><td>The shipping method&#39;s display title — may be <code>null</code>.</td></tr><tr><td><code>baseShippingAmount</code></td><td><code>Float</code></td><td>Shipping price in the store&#39;s base currency — may be <code>null</code>.</td></tr><tr><td><code>formattedBaseShippingAmount</code></td><td><code>String</code></td><td>The same shipping price pre-formatted for display — may be <code>null</code>.</td></tr></tbody></table><h3 id="address-objects-billingaddress-shippingaddress" tabindex="-1">Address objects (<code>billingAddress</code>, <code>shippingAddress</code>) <a class="header-anchor" href="#address-objects-billingaddress-shippingaddress" aria-label="Permalink to &quot;Address objects (`billingAddress`, `shippingAddress`)&quot;">​</a></h3><p>Each is returned as a whole JSON object — query it as a bare field (<code>shippingAddress</code>), you cannot sub-select its keys in the query. The keys below are returned inside each object.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>Int</code></td><td>Address row id.</td></tr><tr><td><code>addressType</code></td><td><code>String</code></td><td><code>order_billing</code> or <code>order_shipping</code>.</td></tr><tr><td><code>firstName</code> / <code>lastName</code></td><td><code>String</code></td><td>Recipient name.</td></tr><tr><td><code>city</code></td><td><code>String</code></td><td>City.</td></tr><tr><td><code>country</code></td><td><code>String</code></td><td>Country code (e.g. <code>US</code>).</td></tr><tr><td><code>postcode</code></td><td><code>String</code></td><td>Postal code.</td></tr><tr><td><code>email</code></td><td><code>String</code></td><td>Contact email.</td></tr><tr><td><code>phone</code></td><td><code>String</code></td><td>Contact phone.</td></tr></tbody></table><h3 id="shipped-items-items" tabindex="-1">Shipped items (<code>items</code>) <a class="header-anchor" href="#shipped-items-items" aria-label="Permalink to &quot;Shipped items (`items`)&quot;">​</a></h3><p><code>items</code> is returned as a whole JSON array — query it as a bare field (<code>items</code>), you cannot sub-select its keys in the query. Each entry has the keys below.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>Int</code></td><td>Shipment-item row id.</td></tr><tr><td><code>orderItemId</code></td><td><code>Int</code></td><td>The order line this shipped item maps to.</td></tr><tr><td><code>sku</code></td><td><code>String</code></td><td>Product SKU.</td></tr><tr><td><code>name</code></td><td><code>String</code></td><td>Product name.</td></tr><tr><td><code>qty</code></td><td><code>Float</code></td><td>Quantity shipped for this line.</td></tr></tbody></table>',18)]))}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
